import { lazy, Suspense, useEffect, useMemo, useState } from "react";

import { presentBaseerApiError } from "./baseer-api-error";
import { BaseerButton } from "./baseer-button";
import { BaseerCard } from "./baseer-card";
import { BaseerCombobox } from "./baseer-combobox";
import { BaseerCompanyReadQuery } from "./baseer-company-read-query";
import { BaseerDatePicker } from "./baseer-date-picker";
import { BaseerEmptyState } from "./baseer-workspace";
import { BaseerFormDialog } from "./baseer-form-dialog";
import { useBaseerForm, z } from "./baseer-form-state";
import { BaseerFilterSelect, BaseerFilterToggle } from "./baseer-filter-controls";
import { BaseerPeriodFilter, defaultBaseerPeriodRange, type BaseerPeriodRange } from "./baseer-period-filter";
import { DailySalesSignIn } from "./daily-sales-sign-in";
import { activeSession, api, requestId, type ActiveSession } from "./daily-sales-client";
import { stageMarketingFinanceHandoff } from "./marketing-finance-handoff";

const LazyMarketingTimelineChart = lazy(() => import("./baseer-chart").then((module) => ({ default: module.BaseerMarketingTimelineChart })));

type Language = "ar" | "en";
type Campaign = { id: string; titleAr: string; titleEn: string | null; platform: "MANUAL" | "GOOGLE_ADS" | "META" | "TIKTOK" | "SNAPCHAT" | "OTHER"; externalReference: string | null; startsOn: string | null; endsOn: string | null; status: "DRAFT" | "PLANNED" | "ACTIVE" | "COMPLETED" | "CANCELLED" | "ARCHIVED"; objective: string | null; notes: string | null; plannedCost: string | null; plannedCurrencyCode: string | null; createdAt: string; updatedAt: string };
type ReplyPolicy = { automationStatus: "DISABLED" | "ENABLED" | "PAUSED"; authoringMethod: "TEMPLATE" | "BASIRA_DRAFT"; tone: "WARM" | "PROFESSIONAL" | "FORMAL"; languageMode: "MATCH_REVIEW" | "ARABIC" | "ENGLISH"; autoFourFiveEnabled: boolean; autoThreeIfSafe: boolean; signature: string | null; revision: number; executionReadiness: "NOT_CONNECTED" };
type ReplyPolicyDraft = Omit<ReplyPolicy, "revision" | "executionReadiness">;
type Workspace = { companyId: string; campaigns: Campaign[]; readiness: Array<{ provider: "GOOGLE_ADS" | "GOOGLE_BUSINESS"; status: "NOT_CONNECTED"; messageAr: string }>; replyPolicy: ReplyPolicy };
type Draft = { titleAr: string; titleEn: string; platform: Campaign["platform"]; startsOn: string; endsOn: string; status: Exclude<Campaign["status"], "ARCHIVED">; objective: string; notes: string; externalReference: string; plannedCost: string };

const blank = (): Draft => ({ titleAr: "", titleEn: "", platform: "MANUAL", startsOn: "", endsOn: "", status: "DRAFT", objective: "", notes: "", externalReference: "", plannedCost: "" });
const visible = (codes: readonly string[] | null, capability: string) => codes === null || codes.includes(capability);
const campaignStatuses: Campaign["status"][] = ["DRAFT", "PLANNED", "ACTIVE", "COMPLETED", "CANCELLED", "ARCHIVED"];
const campaignPlatforms: Campaign["platform"][] = ["MANUAL", "GOOGLE_ADS", "META", "TIKTOK", "SNAPCHAT", "OTHER"];
function campaignStatusLabel(status: Campaign["status"], ar: boolean) {
  return ar ? ({ DRAFT: "مسودة", PLANNED: "مخططة", ACTIVE: "نشطة", COMPLETED: "مكتملة", CANCELLED: "ملغاة", ARCHIVED: "مؤرشفة" } as const)[status] : ({ DRAFT: "Draft", PLANNED: "Planned", ACTIVE: "Active", COMPLETED: "Completed", CANCELLED: "Cancelled", ARCHIVED: "Archived" } as const)[status];
}
function campaignPlatformLabel(platform: Campaign["platform"], ar: boolean) {
  return ar ? ({ MANUAL: "يدوية", GOOGLE_ADS: "Google Ads", META: "Meta", TIKTOK: "TikTok", SNAPCHAT: "Snapchat", OTHER: "أخرى" } as const)[platform] : ({ MANUAL: "Manual", GOOGLE_ADS: "Google Ads", META: "Meta", TIKTOK: "TikTok", SNAPCHAT: "Snapchat", OTHER: "Other" } as const)[platform];
}
function campaignStatusTone(status: Campaign["status"]) { return status === "ACTIVE" || status === "COMPLETED" ? "success" : status === "CANCELLED" ? "danger" : status === "PLANNED" ? "info" : status === "ARCHIVED" ? "neutral" : "warning"; }

export function MarketingWorkspaceContent({ language, section, permissionCodes }: { language: Language; section: number; permissionCodes: readonly string[] | null }) {
  const ar = language === "ar";
  const copy = ar ? {
    eyebrow: "Marketing & Reputation", refresh: "تحديث", newCampaign: "إضافة حملة", title: "الأداء التسويقي والسمعة", overview: "سجل داخلي للحملات؛ لا يخلط بيانات Google أو الحقيقة المالية.", campaigns: "الحملات المسجلة", active: "نشطة", planned: "مخططة", completed: "مكتملة", reputation: "السمعة وGoogle", provider: "الموصل", status: "الحالة", noData: "لا توجد حملة مسجلة بعد", noDataDetail: "ابدأ بتسجيل الحملة وسياقها. لن تُستنتج المبيعات أو التحويلات من هذا السجل.", sources: "حدود المصدر والسياسة", sourcesDetail: "Google Ads قراءة وتحليل فقط لاحقاً. Google Business يمر لاحقاً عبر ناشر يدوي مؤكد، وليس نشرًا آليًا.", edit: "تعديل", archive: "أرشفة", save: "حفظ الحملة", editTitle: "تعديل الحملة", createTitle: "إضافة حملة", titleAr: "اسم الحملة بالعربية", titleEn: "اسم الحملة بالإنجليزية (اختياري)", platform: "المنصة", from: "من", to: "إلى", lifecycle: "الحالة", objective: "الهدف (اختياري)", notes: "ملاحظة داخلية (اختيارية)", ref: "مرجع خارجي وصفي (اختياري)", cancel: "إلغاء", fail: "تعذر إتمام طلب الحملة.", archived: "تمت الأرشفة.", reason: "سبب الأرشفة", archiveTitle: "أرشفة الحملة", archiveText: "لا يتم حذف السجل؛ تحفظ الأرشفة أثر الحملة وسجل التدقيق.", archiveConfirm: "أرشفة", notConnected: "غير متصل", notReady: "لا توجد حقائق موفر أو أرقام سمعة في هذه المرحلة.", noWrite: "لا يوجد نشر أو رد تلقائي أو اتصال Google الآن.", quality: "حالة البيانات", dataBoundary: "غير متاح حتى الاتصال المعتمد", sectionHint: "تُعرض حالة الجاهزية بصدق ولا تُحوّل إلى صفر.", replyAutomation: "الردود التلقائية", replyAutomationHelp: "اضبط السياسة الآن؛ لن تنشر خارجياً قبل ربط Google Business واعتماد النشر.", automationOn: "تشغيل الردود عند الربط", autoFourFive: "رد تلقائي لتقييمات 4 و5 نجوم", autoThree: "رد تلقائي لتقييم 3 نجوم إذا كان آمناً", lowManual: "تقييمات 1 و2 نجمة: مسودة فقط ثم نشر يدوي", threeRule: "الثلاث نجوم تذهب للمراجعة عند وجود شكوى أو طلب استرجاع أو موضوع حساس.", method: "طريقة كتابة الرد", template: "قوالب آمنة", basira: "مسودة بصيرة بعد تفعيلها", tone: "نبرة الرد", warm: "ودودة", professional: "مهنية", formal: "رسمية", languageMode: "لغة الرد", matchReview: "نفس لغة التقييم", arabic: "العربية", english: "الإنجليزية", signature: "توقيع الرد (اختياري)", savePolicy: "حفظ سياسة الردود", policySaved: "تم حفظ سياسة الردود.", policyFail: "تعذر حفظ سياسة الردود.", paused: "موقوف مؤقتاً", activeWhenConnected: "سيعمل عند اكتمال الربط", publisherUnavailable: "زر «نشر الآن» وطابور المراجعة سيظهران هنا بعد الربط؛ لا يوجد نشر فعلي الآن.", automationStatus: "حالة الأتمتة", disabled: "متوقفة", enabled: "مفعلة عند الربط" } : {
    eyebrow: "Marketing & Reputation", refresh: "Refresh", newCampaign: "Add campaign", title: "Marketing performance & reputation", overview: "An internal campaign register. It never mixes Google data with financial truth.", campaigns: "Registered campaigns", active: "Active", planned: "Planned", completed: "Completed", reputation: "Reputation & Google", provider: "Provider", status: "Status", noData: "No campaign is recorded yet", noDataDetail: "Start by recording campaign context. This register never infers sales or conversions.", sources: "Source and policy boundary", sourcesDetail: "Google Ads will be read and analysed only. Google Business will later use a manually confirmed publisher, never automation.", edit: "Edit", archive: "Archive", save: "Save campaign", editTitle: "Edit campaign", createTitle: "Add campaign", titleAr: "Arabic campaign title", titleEn: "English campaign title (optional)", platform: "Platform", from: "From", to: "To", lifecycle: "Status", objective: "Objective (optional)", notes: "Internal note (optional)", ref: "Descriptive external reference (optional)", cancel: "Cancel", fail: "The campaign request could not be completed.", archived: "Archived.", reason: "Archive reason", archiveTitle: "Archive campaign", archiveText: "The record is not deleted. Archiving preserves campaign context and audit history.", archiveConfirm: "Archive", notConnected: "Not connected", notReady: "No provider facts or reputation numbers exist at this stage.", noWrite: "There is no Google publishing, reply automation, or connection now.", quality: "Data status", dataBoundary: "Unavailable until an approved connection", sectionHint: "Readiness is shown honestly and never converted to zero.", replyAutomation: "Automated replies", replyAutomationHelp: "Configure the policy now. It cannot publish until Google Business is connected and publishing is approved.", automationOn: "Enable replies after connection", autoFourFive: "Automatically reply to 4 and 5 star reviews", autoThree: "Automatically reply to safe 3 star reviews", lowManual: "1 and 2 star reviews: draft only, then manual publishing", threeRule: "Three-star reviews are held when they contain a complaint, refund request, or sensitive subject.", method: "Reply authoring", template: "Safe templates", basira: "Basira draft after activation", tone: "Reply tone", warm: "Warm", professional: "Professional", formal: "Formal", languageMode: "Reply language", matchReview: "Match review language", arabic: "Arabic", english: "English", signature: "Reply signature (optional)", savePolicy: "Save reply policy", policySaved: "Reply policy saved.", policyFail: "The reply policy could not be saved.", paused: "Paused", activeWhenConnected: "Will operate after connection", publisherUnavailable: "The review queue and Publish now action will appear here after connection; no live publishing exists now.", automationStatus: "Automation status", disabled: "Disabled", enabled: "Enabled after connection" };
  const [session, setSession] = useState<ActiveSession | null>(activeSession());
  const [dialog, setDialog] = useState<"create" | "edit" | "archive" | "details" | null>(null);
  const [selected, setSelected] = useState<Campaign | null>(null);
  const [draft, setDraft] = useState<Draft>(blank);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const writable = visible(permissionCodes, "marketing.campaign.write");
  const canIssueCampaignInvoice = writable && visible(permissionCodes, "finance.purchase_expense.create") && visible(permissionCodes, "finance.purchase_expense.read");
  const canManageReplyPolicy = visible(permissionCodes, "marketing.reputation.policy.manage");
  const canManageGoogleConnection = visible(permissionCodes, "marketing.google-connection.manage");
  const canRead = visible(permissionCodes, "marketing.insights.read");
  const canUseBasira = canRead && visible(permissionCodes, "platform.ai.use");
  useEffect(() => setSession(activeSession()), []);
  const scope = useMemo(() => [language, String(section), [...(permissionCodes ?? [])].sort().join(",")], [language, section, permissionCodes]);
  const openCreate = () => { setSelected(null); setDraft(blank()); setMessage(null); setDialog("create"); };
  const openEdit = (campaign: Campaign) => { setSelected(campaign); setDraft({ titleAr: campaign.titleAr, titleEn: campaign.titleEn ?? "", platform: campaign.platform, startsOn: campaign.startsOn ?? "", endsOn: campaign.endsOn ?? "", status: campaign.status === "ARCHIVED" ? "DRAFT" : campaign.status, objective: campaign.objective ?? "", notes: campaign.notes ?? "", externalReference: campaign.externalReference ?? "", plannedCost: campaign.plannedCost ?? "" }); setMessage(null); setDialog("edit"); };
  const submit = async (values: Draft, reload: () => Promise<void>) => { if (!session || busy) return; setBusy(true); setMessage(null); try { const body = { ...values, titleAr: values.titleAr.trim(), ...(values.titleEn.trim() ? { titleEn: values.titleEn.trim() } : {}), ...(values.startsOn ? { startsOn: values.startsOn } : {}), ...(values.endsOn ? { endsOn: values.endsOn } : {}), ...(values.objective.trim() ? { objective: values.objective.trim() } : {}), ...(values.notes.trim() ? { notes: values.notes.trim() } : {}), ...(values.externalReference.trim() ? { externalReference: values.externalReference.trim() } : {}), ...(values.plannedCost.trim() ? { plannedCost: values.plannedCost.trim() } : {}), idempotencyKey: requestId() }; await api(session, selected ? `/marketing/campaigns/${selected.id}` : "/marketing/campaigns", { method: selected ? "PUT" : "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); setDialog(null); await reload(); } catch (error) { setMessage(presentBaseerApiError(error, language, copy.fail)); } finally { setBusy(false); } };
  const archive = async (reason: string, reload: () => Promise<void>) => { if (!session || !selected || busy) return; setBusy(true); setMessage(null); try { await api(session, "/marketing/campaigns/archive", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ campaignId: selected.id, reason: reason.trim(), idempotencyKey: requestId() }) }); setDialog(null); setMessage(copy.archived); await reload(); } catch (error) { setMessage(presentBaseerApiError(error, language, copy.fail)); } finally { setBusy(false); } };
  if (!session) return <DailySalesSignIn language={language} />;
  if (!canRead) return <section className="baseer-workspace"><BaseerEmptyState title={ar ? "لا تملك صلاحية عرض الأداء التسويقي" : "You cannot view marketing performance"} /></section>;
  return <BaseerCompanyReadQuery session={session} resource="marketing.workspace" scope={scope} load={(current, signal) => api<Workspace>(current, "/marketing", { signal })}>{({ data, loading, error, refetch }) => <section className="baseer-workspace marketing-workspace" dir={ar ? "rtl" : "ltr"}>
    <header className="baseer-section-header"><div className="baseer-section-header__copy"><p className="baseer-section-header__eyebrow">{copy.eyebrow}</p><h2>{copy.title}</h2><p>{copy.overview}</p></div><div className="baseer-section-header__actions"><BaseerButton type="button" variant="secondary" disabled={loading || busy} onClick={() => void refetch()}>{copy.refresh}</BaseerButton>{writable && section <= 1 ? <BaseerButton type="button" disabled={busy} onClick={openCreate}>{copy.newCampaign}</BaseerButton> : null}</div></header>
    {message ? <BaseerCard className="marketing-workspace__message" padding="compact">{message}</BaseerCard> : null}
    {error ? <BaseerCard className="marketing-workspace__message" padding="compact">{copy.fail}</BaseerCard> : null}
    {section === 0 ? <Overview data={data} copy={copy} ar={ar} language={language} session={session} /> : null}
    {section === 1 ? <MarketingCalendar language={language} session={session} /> : null}
    {section === 2 ? <CampaignRegister data={data} copy={copy} ar={ar} writable={writable} onEdit={openEdit} onDetails={(campaign) => { setSelected(campaign); setDialog("details"); }} onArchive={(campaign) => { setSelected(campaign); setDialog("archive"); }} /> : null}
    {section === 3 ? <Reputation data={data} copy={copy} ar={ar} language={language} session={session} canManagePolicy={canManageReplyPolicy} onSaved={refetch} /> : null}
    {section === 4 ? <Policies copy={copy} language={language} session={session} canManageGoogleConnection={canManageGoogleConnection} /> : null}
    <CampaignDialog open={dialog === "create" || dialog === "edit"} language={language} busy={busy} editing={dialog === "edit"} initial={draft} copy={copy} error={message} onClose={() => setDialog(null)} onSubmit={(values) => void submit(values, refetch)} />
    <ArchiveDialog open={dialog === "archive"} language={language} busy={busy} copy={copy} error={message} onClose={() => setDialog(null)} onSubmit={(reason) => void archive(reason, refetch)} />
    <CampaignDetailsDialog open={dialog === "details"} campaign={selected} language={language} session={session} writable={writable} canUseBasira={canUseBasira} canIssueCampaignInvoice={canIssueCampaignInvoice} onClose={() => setDialog(null)} />
  </section>}</BaseerCompanyReadQuery>;
}

function Overview({ data, copy, ar, language, session }: { data: Workspace | undefined; copy: Record<string, string>; ar: boolean; language: Language; session: ActiveSession }) { const campaigns = data?.campaigns ?? []; return <><div className="baseer-metric-grid"><Metric label={copy.campaigns} value={campaigns.length} /><Metric label={copy.active} value={campaigns.filter((item) => item.status === "ACTIVE").length} /><Metric label={copy.planned} value={campaigns.filter((item) => item.status === "PLANNED").length} /><Metric label={copy.completed} value={campaigns.filter((item) => item.status === "COMPLETED").length} /></div><MarketingSpendOverview language={language} session={session} /><BaseerCard className="marketing-workspace__boundary"><strong>{copy.quality}</strong><p>{copy.sectionHint}</p><span>{copy.dataBoundary}</span></BaseerCard><Reputation data={data} copy={copy} ar={ar} /></>; }
function Metric({ label, value }: { label: string; value: number | string }) { return <BaseerCard className="baseer-metric"><small>{label}</small><strong>{value}</strong></BaseerCard>; }
type SpendResult = { plannedCampaignCost: string | null; linkedActualSpend: string; linkedPostedSpendOnly: true; spendDataQuality: string; excludedLinkedDocumentCount: number; officialNetSales: string | null; spendToSalesPercent: string | null; campaignCount: number; salesDataQuality: string; googleAdsStatus: "NOT_CONNECTED"; conclusionAr: string; conclusionEn: string };
type CalendarRead = { period: { fromBusinessDate: string; toBusinessDate: string }; sales: { dataQuality: string; payload: { netAmount: string } }; campaigns: Campaign[]; days: Array<{ businessDate: string; officialNetSales: string | null; salesDayQuality: "READY" | "PENDING" | "PARTIAL" | "MISSING"; linkedActualSpend: string; linkedFinancialDocumentCount: number; activeCampaignIds: string[] }>; context: Array<{ id: string; scope: "GLOBAL" | "AREA" | "COMPANY"; eventKind: string; titleAr: string; startsOn: string; endsOn: string; verificationStatus: string }>; linkedActualGrossAmount: string; spendResult: SpendResult };
function SpendResultCard({ result, language }: { result: SpendResult; language: Language }) { const ar = language === "ar"; return <BaseerCard className="marketing-workspace__boundary"><strong>{ar ? "قراءة الصرف والنتيجة" : "Spend and result read"}</strong><div className="baseer-metric-grid"><Metric label={ar ? "التكلفة المخططة" : "Planned cost"} value={result.plannedCampaignCost ? `${result.plannedCampaignCost} ر.س` : (ar ? "غير محددة" : "Not set")} /><Metric label={ar ? "الصرف المثبت المرتبط" : "Posted linked spend"} value={`${result.linkedActualSpend} ر.س`} /><Metric label={ar ? "المبيعات الرسمية" : "Official sales"} value={result.officialNetSales ? `${result.officialNetSales} ر.س` : "—"} /><Metric label={ar ? "الصرف من مبيعات الفترة" : "Spend / period sales"} value={result.spendToSalesPercent ? `${result.spendToSalesPercent}%` : "—"} /></div><p>{ar ? result.conclusionAr : result.conclusionEn}</p><small>{ar ? `حالة الصرف: ${result.spendDataQuality}. هذا فقط مصروف مالي مثبت مرتبط بالحملة.` : `Spend quality: ${result.spendDataQuality}. This is only posted Finance spend linked to the campaign.`}</small>{result.excludedLinkedDocumentCount ? <small>{ar ? `${result.excludedLinkedDocumentCount} مستند مرتبط خارج فترة الحملة لم يدخل النتيجة.` : `${result.excludedLinkedDocumentCount} linked document(s) outside the campaign period were excluded.`}</small> : null}<small>{ar ? "Google Ads: غير متصل؛ لا توجد تكلفة أو تحويلات إعلانية يمكن ربطها حالياً." : "Google Ads: not connected; no advertising cost or conversions can be linked yet."}</small></BaseerCard>; }
function MarketingSpendOverview({ language, session }: { language: Language; session: ActiveSession }) { const [period, setPeriod] = useState<BaseerPeriodRange>(() => defaultBaseerPeriodRange()); const ar = language === "ar"; return <BaseerCompanyReadQuery session={session} resource="marketing.overview.spend" scope={[period.from, period.to]} load={(current, signal) => api<CalendarRead>(current, `/marketing/calendar?from=${period.from}&to=${period.to}`, { signal })}>{({ data, loading, error }) => <section className="marketing-calendar" aria-busy={loading}><div className="baseer-section-header__actions"><BaseerPeriodFilter language={language} value={period} onChange={setPeriod} presets={["MONTH", "QUARTER", "YEAR", "RANGE"]} allowNonContiguousMonths={false} /></div>{error ? <BaseerEmptyState title={ar ? "تعذر تحميل قراءة الصرف" : "Spend read could not be loaded"} /> : data ? <SpendResultCard result={data.spendResult} language={language} /> : null}</section>}</BaseerCompanyReadQuery>; }
function MarketingCalendar({ language, session }: { language: Language; session: ActiveSession }) {
  const [period, setPeriod] = useState<BaseerPeriodRange>(() => defaultBaseerPeriodRange()); const ar = language === "ar";
  return <BaseerCompanyReadQuery session={session} resource="marketing.calendar" scope={[period.from, period.to, period.preset, period.months.join(",")]} load={(current, signal) => api<CalendarRead>(current, `/marketing/calendar?from=${period.from}&to=${period.to}`, { signal })}>{({ data, loading, error }) => <section className="marketing-calendar" aria-busy={loading}><BaseerCard><div className="baseer-section-header__actions"><BaseerPeriodFilter language={language} value={period} onChange={setPeriod} presets={["MONTH", "QUARTER", "YEAR", "RANGE"]} allowNonContiguousMonths={false} /></div><strong>{ar ? "التقويم التسويقي" : "Marketing calendar"}</strong><p>{ar ? "خط زمني يومي للمبيعات الرسمية، المصروفات المثبتة المرتبطة، الحملات والسياق المنشور. السياق يفسر التزامناً ولا يثبت سبباً." : "A daily timeline of official sales, posted linked spend, campaigns, and published context. Context explains timing; it never proves cause."}</p></BaseerCard>{error ? <BaseerEmptyState title={ar ? "تعذر تحميل التقويم" : "Calendar could not be loaded"} /> : <>{data ? <><div className="baseer-metric-grid"><Metric label={ar ? "صافي المبيعات الرسمي" : "Official net sales"} value={`${data.sales.payload.netAmount} ر.س`} /><Metric label={ar ? "المصروف المرتبط المثبت" : "Posted linked spend"} value={`${data.linkedActualGrossAmount} ر.س`} /><Metric label={ar ? "الحملات في الفترة" : "Campaigns in period"} value={data.campaigns.length} /><Metric label={ar ? "جودة المبيعات" : "Sales data quality"} value={data.sales.dataQuality} /></div><SpendResultCard result={data.spendResult} language={language} /><Suspense fallback={<BaseerCard>{ar ? "جارٍ تحميل الرسم التفاعلي…" : "Loading the interactive chart…"}</BaseerCard>}><LazyMarketingTimelineChart language={language} title={ar ? "الحملات والمبيعات والمصروفات حسب اليوم" : "Daily campaigns, sales, and spend"} days={data.days} campaigns={data.campaigns} context={data.context} asOf={data.period.toBusinessDate} /></Suspense></> : null}</>}<BaseerCard tone="muted"><strong>{ar ? "حدود القراءة" : "Read boundary"}</strong><p>{ar ? "لا يلوّن الرسم اليوم الناقص أو الجزئي كمبيعات صفرية. المصروف هنا هو فقط المستندات المالية المثبتة المرتبطة بحملة، ولا يشمل Google Ads قبل ربطه واعتماده." : "A missing or partial day is not coloured as zero sales. Spend here is only posted Finance documents linked to a campaign; it excludes Google Ads until an approved connection exists."}</p></BaseerCard></section>}</BaseerCompanyReadQuery>;
}
function CampaignRegister({ data, copy, ar, writable, onEdit, onDetails, onArchive }: { data: Workspace | undefined; copy: Record<string, string>; ar: boolean; writable: boolean; onEdit: (campaign: Campaign) => void; onDetails: (campaign: Campaign) => void; onArchive: (campaign: Campaign) => void }) {
  const campaigns = data?.campaigns ?? [];
  const [status, setStatus] = useState<"ALL" | Campaign["status"]>("ALL");
  if (!campaigns.length) return <BaseerEmptyState title={copy.noData} description={copy.noDataDetail} />;
  const filtered = status === "ALL" ? campaigns : campaigns.filter((campaign) => campaign.status === status);
  return <section className="marketing-campaign-register">
    <div className="baseer-filter-bar marketing-campaign-register__filters"><BaseerFilterSelect label={copy.status} value={status} onChange={(event) => setStatus(event.target.value as "ALL" | Campaign["status"])}><option value="ALL">{ar ? "كل الحالات" : "All statuses"}</option>{campaignStatuses.map((item) => <option key={item} value={item}>{campaignStatusLabel(item, ar)}</option>)}</BaseerFilterSelect></div>
    {filtered.length ? <div className="marketing-campaign-list">{filtered.map((campaign) => <BaseerCard key={campaign.id} className="marketing-campaign"><header><div><strong>{ar ? campaign.titleAr : campaign.titleEn ?? campaign.titleAr}</strong><small>{campaignPlatformLabel(campaign.platform, ar)} · {campaign.startsOn ?? "—"} — {campaign.endsOn ?? "—"}</small></div><span className={`baseer-status-badge baseer-status-badge--${campaignStatusTone(campaign.status)}`}><i className="baseer-status-badge__dot" />{campaignStatusLabel(campaign.status, ar)}</span></header>{campaign.objective ? <p>{campaign.objective}</p> : null}{campaign.notes ? <small>{campaign.notes}</small> : null}<footer><BaseerButton type="button" variant="secondary" onClick={() => onDetails(campaign)}>{ar ? "التفاصيل والتحليل" : "Details & analysis"}</BaseerButton>{writable && campaign.status !== "ARCHIVED" ? <><BaseerButton type="button" variant="secondary" onClick={() => onEdit(campaign)}>{copy.edit}</BaseerButton><BaseerButton type="button" variant="quiet" onClick={() => onArchive(campaign)}>{copy.archive}</BaseerButton></> : null}</footer></BaseerCard>)}</div> : <BaseerEmptyState title={ar ? "لا توجد حملات بهذه الحالة" : "No campaigns match this status"} description={ar ? "غيّر الحالة المختارة أو أضف حملة جديدة." : "Choose another status or add a campaign."} />}
  </section>;
}
function Reputation({ data, copy, ar, language, session, canManagePolicy = false, onSaved }: { data: Workspace | undefined; copy: Record<string, string>; ar: boolean; language?: Language; session?: ActiveSession; canManagePolicy?: boolean; onSaved?: () => Promise<void> }) { return <section className="marketing-reputation"><header><h3>{copy.reputation}</h3><p>{copy.notReady}</p></header><div className="baseer-card-grid">{(data?.readiness ?? []).map((item) => <BaseerCard key={item.provider}><strong>{item.provider === "GOOGLE_ADS" ? "Google Ads" : "Google Business"}</strong><span className="baseer-status-badge baseer-status-badge--warning"><i className="baseer-status-badge__dot" />{copy.notConnected}</span><p>{ar ? item.messageAr : item.provider === "GOOGLE_ADS" ? "Google Ads is not connected at this stage; no spend, conversions, or spending decisions are available." : "Google Business is not connected; no reviews, posts, or publishing authority are available at this stage."}</p></BaseerCard>)}</div>{language && session && data ? <ReputationReplyPolicyForm language={language} session={session} policy={data.replyPolicy} copy={copy} canManage={canManagePolicy} onSaved={onSaved} /> : null}<BaseerCard tone="muted"><strong>{copy.noWrite}</strong><p>{copy.publisherUnavailable}</p></BaseerCard></section>; }

type ReputationReplyPolicyForm = ReplyPolicyDraft & { signature: string };

function ReputationReplyPolicyForm({ language, session, policy, copy, canManage, onSaved }: { language: Language; session: ActiveSession; policy: ReplyPolicy; copy: Record<string, string>; canManage: boolean; onSaved?: () => Promise<void> }) {
  const initial = useMemo<ReputationReplyPolicyForm>(() => ({ automationStatus: policy.automationStatus, authoringMethod: policy.authoringMethod, tone: policy.tone, languageMode: policy.languageMode, autoFourFiveEnabled: policy.autoFourFiveEnabled, autoThreeIfSafe: policy.autoThreeIfSafe, signature: policy.signature ?? "" }), [policy]);
  const schema = useMemo(() => z.object({ automationStatus: z.enum(["DISABLED", "ENABLED", "PAUSED"]), authoringMethod: z.enum(["TEMPLATE", "BASIRA_DRAFT"]), tone: z.enum(["WARM", "PROFESSIONAL", "FORMAL"]), languageMode: z.enum(["MATCH_REVIEW", "ARABIC", "ENGLISH"]), autoFourFiveEnabled: z.boolean(), autoThreeIfSafe: z.boolean(), signature: z.string().max(160) }), []);
  const form = useBaseerForm<ReputationReplyPolicyForm>({ values: initial, schema, shouldFocusError: true });
  const values = form.watch();
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const update = async (next: ReputationReplyPolicyForm) => { if (busy || !canManage) return; setBusy(true); setMessage(null); try { await api(session, "/marketing/reputation/reply-policy", { method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...next, ...(next.signature.trim() ? { signature: next.signature.trim() } : {}), idempotencyKey: requestId() }) }); setMessage(copy.policySaved); await onSaved?.(); } catch (error) { setMessage(presentBaseerApiError(error, language, copy.policyFail)); } finally { setBusy(false); } };
  const set = <Key extends keyof ReputationReplyPolicyForm>(key: Key, value: ReputationReplyPolicyForm[Key]) => form.setValue(key, value as never, { shouldDirty: true, shouldValidate: true });
  return <BaseerCard className="marketing-reputation__automation"><header><div><strong>{copy.replyAutomation}</strong><p>{copy.replyAutomationHelp}</p></div><span className="baseer-status-badge baseer-status-badge--warning"><i className="baseer-status-badge__dot" />{policy.automationStatus === "PAUSED" ? copy.paused : policy.automationStatus === "ENABLED" ? copy.activeWhenConnected : copy.disabled}</span></header>{canManage ? <form data-baseer-rhf-form="true" className="marketing-reputation__form" noValidate onSubmit={form.handleSubmit((next) => void update(next))}><label>{copy.automationStatus}<BaseerCombobox label={copy.automationStatus} placeholder={copy.automationStatus} value={values.automationStatus} options={[{ id: "DISABLED", label: copy.disabled }, { id: "ENABLED", label: copy.enabled }, { id: "PAUSED", label: copy.paused }]} onChange={(next) => set("automationStatus", next as ReputationReplyPolicyForm["automationStatus"])} /></label><fieldset><legend>{copy.automationOn}</legend><BaseerFilterToggle label={copy.autoFourFive} checked={values.autoFourFiveEnabled} onChange={(next) => set("autoFourFiveEnabled", next)} /><BaseerFilterToggle label={copy.autoThree} checked={values.autoThreeIfSafe} onChange={(next) => set("autoThreeIfSafe", next)} /><p>{copy.lowManual}</p><p>{copy.threeRule}</p></fieldset><label>{copy.method}<BaseerCombobox label={copy.method} placeholder={copy.method} value={values.authoringMethod} options={[{ id: "TEMPLATE", label: copy.template }, { id: "BASIRA_DRAFT", label: copy.basira }]} onChange={(next) => set("authoringMethod", next as ReputationReplyPolicyForm["authoringMethod"])} /></label><label>{copy.tone}<BaseerCombobox label={copy.tone} placeholder={copy.tone} value={values.tone} options={[{ id: "WARM", label: copy.warm }, { id: "PROFESSIONAL", label: copy.professional }, { id: "FORMAL", label: copy.formal }]} onChange={(next) => set("tone", next as ReputationReplyPolicyForm["tone"])} /></label><label>{copy.languageMode}<BaseerCombobox label={copy.languageMode} placeholder={copy.languageMode} value={values.languageMode} options={[{ id: "MATCH_REVIEW", label: copy.matchReview }, { id: "ARABIC", label: copy.arabic }, { id: "ENGLISH", label: copy.english }]} onChange={(next) => set("languageMode", next as ReputationReplyPolicyForm["languageMode"])} /></label><label>{copy.signature}<input {...form.register("signature")} /></label><footer><BaseerButton type="submit" disabled={busy}>{copy.savePolicy}</BaseerButton>{message ? <small role="status">{message}</small> : null}</footer></form> : <p>{copy.replyAutomationHelp}</p>}</BaseerCard>;
}
type ProviderConnection = { provider: "GOOGLE_ADS" | "GOOGLE_BUSINESS"; status: "NOT_CONNECTED" | "SETUP_REQUESTED" | "AUTHORIZING" | "BLOCKED"; setupRequestedAt: string | null; platformReadiness: "PLATFORM_SETUP_REQUIRED" | "PLATFORM_READY_AWAITING_OAUTH_IMPLEMENTATION"; allowedOperation: "ADS_READ_ONLY" | "BUSINESS_READ_AND_GOVERNED_PUBLISH"; messageAr: string; messageEn: string };
type ProviderConnectionsRead = { connections: ProviderConnection[]; liveOauthEnabled: false };
function GoogleConnectionCenter({ language, session, canManage }: { language: Language; session: ActiveSession; canManage: boolean }) {
  const ar = language === "ar"; const [busyProvider, setBusyProvider] = useState<ProviderConnection["provider"] | null>(null); const [message, setMessage] = useState<string | null>(null);
  const requestSetup = async (provider: ProviderConnection["provider"], refetch: () => Promise<void>) => { if (!canManage || busyProvider) return; setBusyProvider(provider); setMessage(null); try { await api(session, `/marketing/provider-connections/${provider}/setup-requests`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ idempotencyKey: requestId() }) }); setMessage(ar ? "تم تسجيل طلب التهيئة للشركة. لا يبدأ أي اتصال Google قبل اكتمال إعداد المنصة واعتماد الموصل." : "The company setup request was recorded. No Google connection starts before platform setup and provider approval are complete."); await refetch(); } catch (error) { setMessage(presentBaseerApiError(error, language, ar ? "تعذر تسجيل طلب التهيئة." : "The setup request could not be recorded.")); } finally { setBusyProvider(null); } };
  const beginAuthorization = async (provider: ProviderConnection["provider"]) => { if (!canManage || busyProvider) return; setBusyProvider(provider); try { const result = await api<{ authorizationUrl: string }>(session, `/marketing/provider-connections/${provider}/authorization`, { method: "POST" }); window.location.assign(result.authorizationUrl); } catch (error) { setMessage(presentBaseerApiError(error, language, ar ? "تعذر بدء موافقة Google." : "Google consent could not start.")); setBusyProvider(null); } };
  return <BaseerCompanyReadQuery session={session} resource="marketing.provider-connections" scope={[String(canManage)]} load={(current, signal) => api<ProviderConnectionsRead>(current, "/marketing/provider-connections", { signal })}>{({ data, error, refetch }) => { const platformReady = data?.connections.length === 2 && data.connections.every((connection) => connection.platformReadiness !== "PLATFORM_SETUP_REQUIRED"); return <BaseerCard className="marketing-workspace__boundary"><header><div><strong>{ar ? "اتصالات Google" : "Google connections"}</strong><p>{ar ? "تُدار الشركة من هذه الواجهة لاحقاً؛ لا يدخل المستخدم مفاتيح أو يختار حساباً تلقائياً." : "This will manage company self-service later; users never enter secrets or have an account selected automatically."}</p></div><span className={`baseer-status-badge ${platformReady ? "baseer-status-badge--info" : "baseer-status-badge--warning"}`}><i className="baseer-status-badge__dot" />{platformReady ? (ar ? "إعداد المنصة مكتمل" : "Platform configuration ready") : (ar ? "إعداد المنصة مطلوب" : "Platform setup required")}</span></header><BaseerCard tone="muted"><strong>{ar ? "كيف سيعمل الربط؟" : "How connection will work"}</strong><ol><li>{ar ? "إعداد منصة Google مرة واحدة: المشروع والسياسات والأسرار الخادمية." : "One-time platform setup: project, policies, and server-side secrets."}</li><li>{ar ? "مسؤول الشركة يضغط «ربط Google» من هنا ويمنح الموافقة في Google." : "The company manager selects Connect Google here and grants consent in Google."}</li><li>{ar ? "يعرض Baseer الحسابات أو المواقع المتاحة ليختار المسؤول واحداً صراحةً، ثم يبدأ الاستيراد بعد التحقق." : "Baseer shows available accounts or locations for explicit selection, then starts import only after validation."}</li></ol><small>{platformReady ? (ar ? "المنصة جاهزة على الخادم. يبقى تفعيل رحلة OAuth المراجعة قبل ظهور زر ربط Google الحي." : "The server platform is ready. The reviewed OAuth journey remains to be enabled before live Connect Google appears.") : (ar ? "الزر الحالي يسجل المرحلة الأولى فقط لأن إعداد المنصة لم يُعتمد بعد." : "The current button records only step one because the platform setup is not approved yet.")}</small></BaseerCard>{error ? <BaseerEmptyState title={ar ? "تعذر قراءة حالة الموصلات" : "Provider status could not be read"} /> : <div className="baseer-card-grid">{(data?.connections ?? []).map((connection) => <BaseerCard key={connection.provider} tone="muted"><strong>{connection.provider === "GOOGLE_ADS" ? "Google Ads" : "Google Business"}</strong><p>{ar ? connection.messageAr : connection.messageEn}</p><small>{connection.provider === "GOOGLE_ADS" ? (ar ? "المسموح لاحقاً: قراءة وتحليل فقط؛ لا حملات أو إنفاق أو تعديل." : "Later scope: read and analysis only; no campaigns, spending, or changes.") : (ar ? "المسموح لاحقاً: قراءة، ثم نشر محكوم بموافقة وإيصال." : "Later scope: read, then governed publishing with confirmation and receipt.")}</small><footer>{connection.status === "SETUP_REQUESTED" ? <span className="baseer-status-badge baseer-status-badge--info"><i className="baseer-status-badge__dot" />{ar ? "طلب التهيئة مسجل — بانتظار تجهيز المنصة" : "Setup requested — awaiting platform preparation"}</span> : canManage ? <BaseerButton type="button" variant="secondary" disabled={busyProvider !== null} onClick={() => void requestSetup(connection.provider, refetch)}>{ar ? "طلب تهيئة الربط" : "Request connection setup"}</BaseerButton> : <small>{ar ? "تحتاج صلاحية إدارة ربط Google للشركة." : "You need company Google-connection management permission."}</small>}</footer></BaseerCard>)}</div>}<small>{ar ? "لا توجد حالياً رموز OAuth أو حسابات أو مواقع أو مزامنة أو نشر. فتح رحلة Google الحية يحتاج مشروعاً معتمداً، سياسة موصل، secrets خادمية وPilot محدود." : "There are currently no OAuth tokens, accounts, locations, syncs, or publishing. A live Google flow needs an approved project, provider policy, server-side secrets, and a limited pilot."}</small>{message ? <small role="status">{message}</small> : null}</BaseerCard>; }}</BaseerCompanyReadQuery>;
}
function Policies({ copy, language, session, canManageGoogleConnection }: { copy: Record<string, string>; language: Language; session: ActiveSession; canManageGoogleConnection: boolean }) { return <section className="marketing-reputation"><BaseerCard className="marketing-workspace__boundary"><strong>{copy.sources}</strong><p>{copy.sourcesDetail}</p><ul><li>Google Ads: read-only after a separate provider decision.</li><li>Google Business: governed publisher after explicit confirmation and a provider gate.</li><li>Campaign context is not a finance fact and proves no sales impact.</li></ul></BaseerCard><GoogleConnectionCenter language={language} session={session} canManage={canManageGoogleConnection} /></section>; }

function campaignSchema(ar: boolean) {
  return z.object({
    titleAr: z.string().trim().min(1, ar ? "اسم الحملة بالعربية مطلوب." : "Arabic campaign title is required.").max(160),
    titleEn: z.string().max(160),
    platform: z.enum(["MANUAL", "GOOGLE_ADS", "META", "TIKTOK", "SNAPCHAT", "OTHER"]),
    startsOn: z.string(),
    endsOn: z.string(),
    status: z.enum(["DRAFT", "PLANNED", "ACTIVE", "COMPLETED", "CANCELLED"]),
    objective: z.string().max(500),
    notes: z.string().max(2000),
    externalReference: z.string().max(160),
    plannedCost: z.string().regex(/^$|^\d+(\.\d{1,4})?$/, ar ? "أدخل مبلغاً صحيحاً حتى 4 منازل عشرية." : "Enter a valid amount with up to 4 decimals."),
  }).refine((value) => !value.startsOn || !value.endsOn || value.startsOn <= value.endsOn, {
    path: ["endsOn"],
    message: ar ? "تاريخ النهاية لا يسبق البداية." : "Campaign end cannot precede its start.",
  });
}

type CampaignAnalysis = { period: { fromBusinessDate: string; toBusinessDate: string } | null; sales: { dataQuality: string; payload: { netAmount: string } } | null; salesComparison: { dataQuality: string; payload: { differenceNetAmount: string; percentDifference: string | null; comparisonNetAmount: string } } | null; linkedActualGrossAmount: string; spendResult: SpendResult; managerSummaryAr: string; limitations: string[]; linkedFinancialDocuments: Array<{ documentNumber: string; grossAmount: string; businessDate: string; includedInCampaignPeriod: boolean }>; relatedContext: Array<{ id: string; scope: "GLOBAL" | "AREA" | "COMPANY"; titleAr: string; startsOn: string; endsOn: string; explicitlyLinked: boolean }> };
type LinkableFinancialDocuments = { documents: Array<{ id: string; documentNumber: string; businessDate: string; kind: "PURCHASE" | "EXPENSE"; grossAmount: string }> };
function CampaignDetailsDialog({ open, campaign, language, session, writable, canUseBasira, canIssueCampaignInvoice, onClose }: { open: boolean; campaign: Campaign | null; language: Language; session: ActiveSession; writable: boolean; canUseBasira: boolean; canIssueCampaignInvoice: boolean; onClose: () => void }) {
  const ar = language === "ar";
  if (!open || !campaign) return null;
  const issueInvoice = () => { stageMarketingFinanceHandoff({ companyId: session.companyId, campaignId: campaign.id, campaignTitleAr: campaign.titleAr, campaignSummary: [campaign.objective, campaign.notes].filter((item): item is string => Boolean(item?.trim())).join("\n") || null, startsOn: campaign.startsOn, endsOn: campaign.endsOn, plannedCost: campaign.plannedCost }); onClose(); window.location.hash = "module=operations&section=2"; };
  return <BaseerFormDialog open title={ar ? "تفاصيل الحملة وتحليلها" : "Campaign details & analysis"} language={language} formId="marketing-campaign-analysis" submitLabel={ar ? "إغلاق" : "Close"} onClose={onClose} busy={false} size="wide"><BaseerCompanyReadQuery session={session} resource="marketing.campaign.analysis" scope={[campaign.id]} load={(current, signal) => api<CampaignAnalysis>(current, `/marketing/campaigns/${campaign.id}/analysis`, { signal })}>{({ data, loading, error, refetch }) => <form id="marketing-campaign-analysis" className="marketing-campaign-form" onSubmit={(event) => { event.preventDefault(); onClose(); }}>{loading ? <p>{ar ? "جارٍ تحميل القراءة الرسمية…" : "Loading the official read…"}</p> : null}{error ? <BaseerEmptyState title={ar ? "تعذر تحميل تحليل الحملة" : "Campaign analysis could not be loaded"} /> : null}{data ? <><BaseerCard><strong>{ar ? "ما حدث في الفترة" : "What happened in the period"}</strong><p>{data.period ? `${data.period.fromBusinessDate} — ${data.period.toBusinessDate}` : ar ? "أضف فترة للحملة لقراءة المبيعات والسياق." : "Add campaign dates to read sales and context."}</p><div className="baseer-metric-grid"><Metric label={ar ? "صافي المبيعات الرسمي" : "Official net sales"} value={data.sales?.payload.netAmount ? `${data.sales.payload.netAmount} ر.س` : "—"} /><Metric label={ar ? "جودة البيانات" : "Data quality"} value={data.sales?.dataQuality ?? "NO_DATA"} /><Metric label={ar ? "المصروف المرتبط المثبت" : "Posted linked spend"} value={`${data.linkedActualGrossAmount} ر.س`} /></div></BaseerCard><BaseerCard><strong>{ar ? "القراءة الموحدة للحملة" : "Unified campaign reading"}</strong><p>{data.managerSummaryAr}</p>{data.salesComparison ? <div className="baseer-metric-grid"><Metric label={ar ? "مبيعات الفترة السابقة" : "Previous equal-period sales"} value={`${data.salesComparison.payload.comparisonNetAmount} ر.س`} /><Metric label={ar ? "فرق المبيعات" : "Sales difference"} value={`${data.salesComparison.payload.differenceNetAmount} ر.س`} /><Metric label={ar ? "نسبة التغير" : "Change percent"} value={data.salesComparison.payload.percentDifference ? `${data.salesComparison.payload.percentDifference}%` : "—"} /><Metric label={ar ? "جودة المقارنة" : "Comparison quality"} value={data.salesComparison.dataQuality} /></div> : null}<ul>{data.limitations.map((limit) => <li key={limit}>{limit}</li>)}</ul></BaseerCard>{canUseBasira ? <CampaignBasiraExplanation campaignId={campaign.id} language={language} session={session} eligible={Boolean(data.period && data.salesComparison?.dataQuality === "READY")} /> : null}<SpendResultCard result={data.spendResult} language={language} /><BaseerCard><strong>{ar ? "المستندات المالية المرتبطة" : "Linked financial documents"}</strong><p>{data.linkedFinancialDocuments.length ? data.linkedFinancialDocuments.map((item) => `${item.documentNumber} · ${item.grossAmount} ر.س · ${item.businessDate}${item.includedInCampaignPeriod ? "" : (ar ? " · خارج فترة الحملة" : " · outside campaign period")}`).join("\n") : ar ? "لا يوجد مستند مثبت مرتبط بعد." : "No posted document is linked yet."}</p>{canIssueCampaignInvoice ? <BaseerButton type="button" onClick={issueInvoice}>{ar ? "إصدار فاتورة/مصروف للحملة" : "Issue a campaign invoice/expense"}</BaseerButton> : null}{writable ? <CampaignFinancialLinker campaignId={campaign.id} language={language} session={session} onLinked={refetch} /> : null}</BaseerCard><BaseerCard><strong>{ar ? "السياق المتزامن" : "Concurrent context"}</strong><p>{data.relatedContext.length ? data.relatedContext.map((item) => `${item.titleAr} · ${item.startsOn} — ${item.endsOn}${item.explicitlyLinked ? " · مرتبط" : ""}`).join("\n") : ar ? "لا توجد مناسبة أو أحداث منشورة متداخلة." : "No published events overlap this period."}</p>{writable ? <CampaignContextLinker campaignId={campaign.id} language={language} session={session} items={data.relatedContext} onLinked={refetch} /> : null}<small>{ar ? "يعرض هذا تزامناً زمنياً فقط، ولا يثبت أن الحملة أو الحدث سبب تغير المبيعات." : "This is temporal context only; it does not prove that a campaign or event caused a sales change."}</small></BaseerCard></> : null}</form>}</BaseerCompanyReadQuery></BaseerFormDialog>;
}

type CampaignExplanationReceipt = { evidenceSnapshotId: string; explanation: { summary: string; evidence: string[]; limitations: string[]; reviewSteps: string[] } };
function CampaignBasiraExplanation({ campaignId, language, session, eligible }: { campaignId: string; language: Language; session: ActiveSession; eligible: boolean }) {
  const ar = language === "ar"; const [busy, setBusy] = useState(false); const [error, setError] = useState<string | null>(null); const [result, setResult] = useState<CampaignExplanationReceipt | null>(null);
  const explain = async () => { if (!eligible || busy) return; setBusy(true); setError(null); try { setResult(await api<CampaignExplanationReceipt>(session, "/administration/ai/runtime/marketing-campaign-explanations", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ campaignId, language, idempotencyKey: requestId() }) })); } catch (reason) { setError(presentBaseerApiError(reason, language, ar ? "بصيرة غير مفعلة أو تعذر التفسير الآن." : "Basira is not enabled or the explanation is unavailable.")); } finally { setBusy(false); } };
  return <BaseerCard className="marketing-workspace__boundary"><strong>{ar ? "تفسير بصيرة" : "Basira explanation"}</strong><p>{ar ? "تفسّر بصيرة حزمة أدلة مجمّدة لهذه الحملة فقط. لا تعدّل الحملة أو الفواتير أو Google." : "Basira explains a frozen evidence package for this campaign only. It never changes the campaign, Finance, or Google."}</p><BaseerButton type="button" variant="secondary" disabled={!eligible || busy} onClick={() => void explain()}>{busy ? (ar ? "جارٍ تجهيز التفسير…" : "Preparing explanation…") : (ar ? "اطلب تفسير بصيرة" : "Ask Basira")}</BaseerButton>{!eligible ? <small>{ar ? "يلزم تاريخ للحملة ومبيعات حالية ومقارنة مكتملة قبل طلب التفسير." : "Campaign dates and complete current/comparison sales are required before an explanation."}</small> : null}{error ? <small role="alert">{error}</small> : null}{result ? <div className="decision-basira-explanation"><p><strong>{result.explanation.summary}</strong></p><strong>{ar ? "الدليل" : "Evidence"}</strong><ul>{result.explanation.evidence.map((item) => <li key={item}>{item}</li>)}</ul><strong>{ar ? "القيود" : "Limitations"}</strong><ul>{result.explanation.limitations.map((item) => <li key={item}>{item}</li>)}</ul><strong>{ar ? "خطوات المراجعة" : "Review steps"}</strong><ul>{result.explanation.reviewSteps.map((item) => <li key={item}>{item}</li>)}</ul><small>{ar ? "حُفظت حزمة الأدلة لهذا التفسير للمراجعة؛ النتيجة لا تثبت السببية." : "An evidence package is retained for this explanation; the result does not prove causation."}</small><CampaignAnalysisFeedback campaignId={campaignId} evidenceSnapshotId={result.evidenceSnapshotId} language={language} session={session} /></div> : null}</BaseerCard>;
}

function CampaignAnalysisFeedback({ campaignId, evidenceSnapshotId, language, session }: { campaignId: string; evidenceSnapshotId: string; language: Language; session: ActiveSession }) {
  const ar = language === "ar"; const [busy, setBusy] = useState(false); const [message, setMessage] = useState<string | null>(null);
  const choices = ar ? [{ kind: "USEFUL", label: "مفيد" }, { kind: "NOT_RELEVANT", label: "غير مناسب" }, { kind: "DATA_INCOMPLETE", label: "البيانات ناقصة" }, { kind: "COMPARISON_UNFAIR", label: "المقارنة غير عادلة" }, { kind: "DIFFERENT_CONTEXT", label: "السياق مختلف" }] : [{ kind: "USEFUL", label: "Useful" }, { kind: "NOT_RELEVANT", label: "Not relevant" }, { kind: "DATA_INCOMPLETE", label: "Data incomplete" }, { kind: "COMPARISON_UNFAIR", label: "Unfair comparison" }, { kind: "DIFFERENT_CONTEXT", label: "Different context" }];
  const submit = async (kind: string) => { if (busy) return; setBusy(true); setMessage(null); try { await api(session, `/marketing/campaigns/${campaignId}/analysis-feedback`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ evidenceSnapshotId, kind, idempotencyKey: requestId() }) }); setMessage(ar ? "تم حفظ تقييمك لتحسين القراءة مستقبلاً؛ لا يتعلم النظام أو يغير البيانات تلقائياً." : "Your evaluation was saved for future review; it does not automatically train or change data."); } catch (reason) { setMessage(presentBaseerApiError(reason, language, ar ? "تعذر حفظ التقييم." : "Feedback could not be saved.")); } finally { setBusy(false); } };
  return <div className="marketing-campaign-linker"><small>{ar ? "هل ساعدك هذا التفسير؟" : "Did this explanation help?"}</small>{choices.map((choice) => <BaseerButton key={choice.kind} type="button" variant="quiet" disabled={busy} onClick={() => void submit(choice.kind)}>{choice.label}</BaseerButton>)}{message ? <small role="status">{message}</small> : null}</div>;
}

function CampaignFinancialLinker({ campaignId, language, session, onLinked }: { campaignId: string; language: Language; session: ActiveSession; onLinked: () => Promise<void> }) {
  const ar = language === "ar"; const [selected, setSelected] = useState(""); const [busy, setBusy] = useState(false); const [message, setMessage] = useState<string | null>(null);
  const link = async () => { if (!selected || busy) return; setBusy(true); setMessage(null); try { await api(session, `/marketing/campaigns/${campaignId}/financial-documents`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ financialDocumentId: selected, idempotencyKey: requestId() }) }); setSelected(""); setMessage(ar ? "تم ربط المستند المثبت." : "The posted document was linked."); await onLinked(); } catch (error) { setMessage(presentBaseerApiError(error, language, ar ? "تعذر ربط المستند." : "The document could not be linked.")); } finally { setBusy(false); } };
  return <BaseerCompanyReadQuery session={session} resource="marketing.campaign.linkable-financial-documents" scope={[campaignId]} load={(current, signal) => api<LinkableFinancialDocuments>(current, `/marketing/campaigns/${campaignId}/financial-documents/available`, { signal })}>{({ data, error }) => <div className="marketing-campaign-linker">{error ? <small>{ar ? "لا تملك صلاحية عرض المستندات أو لا توجد مستندات قابلة للربط." : "You cannot view linkable documents, or none are available."}</small> : <><BaseerCombobox label={ar ? "ربط مستند مالي مثبت" : "Link a posted financial document"} placeholder={ar ? "اختر مستنداً" : "Choose a document"} value={selected} options={(data?.documents ?? []).map((item) => ({ id: item.id, label: `${item.documentNumber} · ${item.grossAmount} ر.س · ${item.businessDate}` }))} onChange={setSelected} /><BaseerButton type="button" variant="secondary" disabled={!selected || busy} onClick={() => void link()}>{ar ? "ربط المستند" : "Link document"}</BaseerButton></>}{message ? <small role="status">{message}</small> : null}</div>}</BaseerCompanyReadQuery>;
}

function CampaignContextLinker({ campaignId, language, session, items, onLinked }: { campaignId: string; language: Language; session: ActiveSession; items: CampaignAnalysis["relatedContext"]; onLinked: () => Promise<void> }) {
  const ar = language === "ar"; const [busyId, setBusyId] = useState<string | null>(null); const [message, setMessage] = useState<string | null>(null);
  const link = async (item: CampaignAnalysis["relatedContext"][number]) => { setBusyId(item.id); setMessage(null); try { await api(session, `/marketing/campaigns/${campaignId}/context`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ ...(item.scope === "COMPANY" ? { companyEventId: item.id } : { globalEventId: item.id }), idempotencyKey: requestId() }) }); setMessage(ar ? "تم تمييز السياق كمرجع صريح للحملة." : "The context was marked as an explicit campaign reference."); await onLinked(); } catch (error) { setMessage(presentBaseerApiError(error, language, ar ? "تعذر ربط السياق." : "The context could not be linked.")); } finally { setBusyId(null); } };
  const candidates = items.filter((item) => !item.explicitlyLinked);
  return candidates.length ? <div className="marketing-campaign-linker"><small>{ar ? "يمكن تمييز مناسبة متزامنة كمرجع للحملة؛ لا يثبت ذلك أنها سبب النتيجة." : "A concurrent event can be marked as a campaign reference; this never proves causation."}</small>{candidates.map((item) => <BaseerButton key={item.id} type="button" variant="quiet" disabled={busyId !== null} onClick={() => void link(item)}>{ar ? `ربط: ${item.titleAr}` : `Link: ${item.titleAr}`}</BaseerButton>)}{message ? <small role="status">{message}</small> : null}</div> : null;
}

function CampaignDialog({ open, language, busy, editing, initial, copy, error, onClose, onSubmit }: { open: boolean; language: Language; busy: boolean; editing: boolean; initial: Draft; copy: Record<string, string>; error: string | null; onClose: () => void; onSubmit: (values: Draft) => void }) {
  const ar = language === "ar";
  const schema = useMemo(() => campaignSchema(ar), [ar]);
  const form = useBaseerForm<Draft>({ values: initial, schema, shouldFocusError: true });
  const value = form.watch();
  const set = (key: keyof Draft, next: string) => form.setValue(key, next as never, { shouldDirty: true, shouldValidate: true });
  const fieldError = (name: keyof Draft) => form.formState.errors[name]?.message;
  return <BaseerFormDialog open={open} title={editing ? copy.editTitle : copy.createTitle} language={language} formId="marketing-campaign-form" submitLabel={copy.save} onClose={onClose} busy={busy} error={error} size="wide">
    <form id="marketing-campaign-form" data-baseer-rhf-form="true" className="marketing-campaign-form" noValidate onSubmit={form.handleSubmit((values) => onSubmit(values))}>
      <label>{copy.titleAr}<input aria-invalid={Boolean(fieldError("titleAr"))} {...form.register("titleAr")} autoFocus /></label>{fieldError("titleAr") ? <small className="baseer-field-error" role="alert">{fieldError("titleAr")}</small> : null}
      <label>{copy.titleEn}<input {...form.register("titleEn")} /></label>
      <label>{copy.platform}<BaseerCombobox label={copy.platform} placeholder={ar ? "اختر المنصة" : "Select platform"} value={value.platform} options={campaignPlatforms.map((item) => ({ id: item, label: campaignPlatformLabel(item, ar) }))} onChange={(next) => set("platform", next)} /></label>
      <div className="marketing-campaign-form__dates"><label>{copy.from}<BaseerDatePicker language={language} label={copy.from} value={value.startsOn} onChange={(next) => set("startsOn", next)} /></label><label>{copy.to}<BaseerDatePicker language={language} label={copy.to} value={value.endsOn} onChange={(next) => set("endsOn", next)} /></label></div>{fieldError("endsOn") ? <small className="baseer-field-error" role="alert">{fieldError("endsOn")}</small> : null}
      <label>{copy.lifecycle}<BaseerCombobox label={copy.lifecycle} placeholder={ar ? "اختر الحالة" : "Select status"} value={value.status} options={campaignStatuses.filter((item) => item !== "ARCHIVED").map((item) => ({ id: item, label: campaignStatusLabel(item, ar) }))} onChange={(next) => set("status", next)} /></label>
      <label>{ar ? "التكلفة المخططة (ر.س، اختيارية)" : "Planned cost (SAR, optional)"}<input inputMode="decimal" {...form.register("plannedCost")} /></label>
      <label>{copy.objective}<textarea {...form.register("objective")} /></label>{fieldError("objective") ? <small className="baseer-field-error" role="alert">{fieldError("objective")}</small> : null}
      <label>{copy.notes}<textarea {...form.register("notes")} /></label>{fieldError("notes") ? <small className="baseer-field-error" role="alert">{fieldError("notes")}</small> : null}
      <label>{copy.ref}<input {...form.register("externalReference")} /></label>{fieldError("externalReference") ? <small className="baseer-field-error" role="alert">{fieldError("externalReference")}</small> : null}
    </form>
  </BaseerFormDialog>;
}

function ArchiveDialog({ open, language, busy, copy, error, onClose, onSubmit }: { open: boolean; language: Language; busy: boolean; copy: Record<string, string>; error: string | null; onClose: () => void; onSubmit: (reason: string) => void }) {
  const ar = language === "ar";
  const schema = useMemo(() => z.object({ reason: z.string().trim().min(1, ar ? "سبب الأرشفة مطلوب." : "An archive reason is required.").max(500) }), [ar]);
  const form = useBaseerForm<{ reason: string }>({ defaultValues: { reason: "" }, schema, shouldFocusError: true });
  useEffect(() => { if (open) form.reset({ reason: "" }); }, [form, open]);
  const reasonError = form.formState.errors.reason?.message;
  return <BaseerFormDialog open={open} title={copy.archiveTitle} language={language} formId="marketing-archive-form" submitLabel={copy.archiveConfirm} onClose={onClose} busy={busy} error={error} size="compact">
    <form id="marketing-archive-form" data-baseer-rhf-form="true" className="marketing-campaign-form" noValidate onSubmit={form.handleSubmit(({ reason }) => onSubmit(reason))}>
      <p>{copy.archiveText}</p><label>{copy.reason}<textarea aria-invalid={Boolean(reasonError)} {...form.register("reason")} autoFocus /></label>{reasonError ? <small className="baseer-field-error" role="alert">{reasonError}</small> : null}
    </form>
  </BaseerFormDialog>;
}
